package es.c10.controlpro;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.net.Uri;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 private LinearLayout page;private TextView status;private LocationManager manager;private LocationListener listener;private Measurements.Timer timer;private String timerLabel="";private String report="";private String completed="";
 private final String[] models={"C10 REEV · 215 CV","C10 BEV","B10","T03","Otro Leapmotor"};
 @Override public void onCreate(Bundle b){super.onCreate(b);home();}
 private void screen(String title){
  timer=null;stopGps();page=new LinearLayout(this);page.setOrientation(1);page.setPadding(24,20,24,20);page.setBackgroundColor(Color.rgb(13,25,36));
  ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(page);setContentView(sc);text(title,24);if(!title.equals("C10 CONTROL PRO · PRUEBA 0.2"))button("Volver al inicio",()->home());
  if(Build.VERSION.SDK_INT>=35)page.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets s=in.getInsets(WindowInsets.Type.systemBars());v.setPadding(s.left+24,s.top+20,s.right+24,s.bottom+20);return in;});
 }
 private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setPadding(0,10,0,10);page.addView(v);return v;}
 private void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);page.addView(b);b.setOnClickListener(v->action.run());}
 private void home(){screen("C10 CONTROL PRO · PRUEBA 0.2");text("Aplicación propia de prueba. No consulta ni controla servicios del vehículo.",17);
  Spinner model=new Spinner(this);model.setBackgroundColor(Color.LTGRAY);model.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,models));model.setSelection(getPreferences(0).getInt("vehicle",0));page.addView(model);model.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int n,long id){getPreferences(0).edit().putInt("vehicle",n).apply();}});
  button("Diagnóstico",()->diagnostic());button("Velocidad y mediciones GPS",()->gpsPage());button("Costes y regeneración estimada",()->calculators());button("Accesos multimedia",()->media());
  text("SIN CONEXIÓN: telemetría CAN, batería real, generador REEV, cámaras, centinela y control remoto. El OBD de ControlPlus no está incluido en esta prueba independiente.",16);
 }
 private boolean allowed(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private String diagnosticText(){return "Modelo seleccionado: "+models[getPreferences(0).getInt("vehicle",0)]+"\nAndroid: "+Build.VERSION.RELEASE+" · API "+Build.VERSION.SDK_INT+"\nArquitecturas: "+Arrays.toString(Build.SUPPORTED_ABIS)+"\nGPS declarado: "+getPackageManager().hasSystemFeature(PackageManager.FEATURE_LOCATION_GPS)+"\nPermiso preciso: "+(allowed()?"concedido":"no concedido")+"\nPaquete: "+getPackageName()+"\nServicios del vehículo: no conectados\nNo se recogen VIN, cuentas ni coordenadas en este informe.";}
 private void diagnostic(){screen("Diagnóstico");report=diagnosticText();text(report,17);button("Guardar informe",()->{try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"C10-Control-Pro-0.2.txt"),7);}catch(Exception e){new AlertDialog.Builder(this).setMessage("No hay selector de archivos disponible.").setPositiveButton("Cerrar",null).show();}});}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==7&&result==RESULT_OK&&data!=null&&data.getData()!=null)try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException();out.write(report.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Informe guardado",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"No se pudo guardar",Toast.LENGTH_LONG).show();}}
 private void gpsPage(){screen("Mediciones GPS");text("Configura estando aparcado. Mediciones orientativas, solo en circuito autorizado. Se detiene al salir de la pantalla. 3–100 NO equivale a 0–100.",16);status=text("GPS detenido",20);
  button("Iniciar GPS",()->startGps());button("Preparar 3–100 km/h",()->arm(3,100));button("Preparar 80–120 km/h",()->arm(80,120));button("Detener medición",()->{timer=null;stopGps();status.setText("GPS detenido");});text("Precisión máxima admitida: 20 m. Muestras con más de 2,5 s entre ellas reinician el cronómetro. Se requiere cruzar el umbral inferior desde una velocidad menor.",16);}
 private void arm(double low,double high){timer=new Measurements.Timer(low,high);timerLabel=(int)low+"–"+(int)high;completed="";startGps();}
 private void startGps(){if(!allowed()){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},1);return;}
  try{manager=(LocationManager)getSystemService(LOCATION_SERVICE);stopGps();if(manager==null||!manager.getAllProviders().contains(LocationManager.GPS_PROVIDER)){status.setText("Este dispositivo no ofrece proveedor GPS.");return;}if(!manager.isProviderEnabled(LocationManager.GPS_PROVIDER)){status.setText("Ubicación desactivada. Actívala en los ajustes normales de Android.");return;}
   listener=new LocationListener(){public void onLocationChanged(Location l){long age=SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos();boolean valid=l.hasSpeed()&&l.hasAccuracy()&&age>=0&&age<=2500000000L;double speed=l.getSpeed()*3.6;String result=valid?String.format(Locale.US,"GPS: %.1f km/h · precisión %.0f m",speed,l.getAccuracy()):"Esperando una muestra GPS válida";
    if(timer!=null){double sec=timer.update(l.getElapsedRealtimeNanos()/1e9,speed,l.hasAccuracy()?l.getAccuracy():Double.NaN,valid);if(!Double.isNaN(sec)){completed=String.format(Locale.US,"\n%s: %.2f s · GPS orientativo",timerLabel,sec);timer=null;}else result+="\n"+timerLabel+": "+(timer.started()?"midiendo":"esperando cruce inicial");}status.setText(result+completed);}
    public void onProviderDisabled(String p){if(timer!=null)timer.reset();status.setText("GPS desactivado");}public void onProviderEnabled(String p){}public void onStatusChanged(String p,int s,Bundle e){}
   };manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,200,0,listener);status.setText("Buscando señal GPS…");
  }catch(SecurityException e){status.setText("Permiso de ubicación no disponible");}catch(Exception e){status.setText("GPS no disponible en este dispositivo");}}
 private void stopGps(){if(manager!=null&&listener!=null)try{manager.removeUpdates(listener);}catch(SecurityException ignored){}listener=null;}
 @Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==1&&status!=null){if(allowed())startGps();else status.setText("Permiso preciso no concedido. La app sigue funcionando sin GPS.");}}
 private EditText number(String hint){EditText v=new EditText(this);v.setTextColor(Color.WHITE);v.setHintTextColor(Color.LTGRAY);v.setHint(hint);v.setInputType(8194);page.addView(v);return v;}
 private double val(EditText v){return Double.parseDouble(v.getText().toString().trim().replace(',','.'));}
 private void calculators(){screen("Costes y estimaciones");text("Entrada manual. No son lecturas del coche.",17);EditText kwh=number("Consumo eléctrico · kWh/100 km"),price=number("Precio electricidad · €/kWh"),litres=number("Consumo gasolina · L/100 km"),fuel=number("Precio gasolina · €/L");TextView cost=text("Sin calcular",18);
  button("Calcular costes separados",()->{try{cost.setText(String.format(Locale.US,"Eléctrico: %.2f €/100 km\nGasolina: %.2f €/100 km",Measurements.cost(val(kwh),val(price)),Measurements.cost(val(litres),val(fuel))));}catch(Exception e){cost.setText("Introduce valores válidos y no negativos.");}});
  text("Regeneración ESTIMADA: potencia media × duración. No mide la frenada real.",17);EditText power=number("Potencia media · kW"),seconds=number("Duración · segundos");TextView energy=text("Sin estimar",18);button("Estimar energía",()->{try{energy.setText(String.format(Locale.US,"Energía estimada: %.4f kWh",Measurements.regenerated(val(power),val(seconds))));}catch(Exception e){energy.setText("Introduce valores válidos y no negativos.");}});}
 private void media(){screen("Accesos multimedia");text("Abren una aplicación o navegador externo. No incluyen suscripciones, reproducción propia ni Android Auto/CarPlay. Solo estando estacionado.",17);button("Spotify",()->parked("https://open.spotify.com"));button("Netflix",()->parked("https://www.netflix.com"));button("HBO / Max",()->parked("https://www.max.com"));button("Pluto TV",()->parked("https://pluto.tv"));button("Google",()->parked("https://www.google.com"));button("Amazon Prime Video",()->parked("https://www.primevideo.com"));}
 private void parked(String url){new AlertDialog.Builder(this).setTitle("Uso estacionado").setMessage("¿El coche está aparcado? Esta confirmación es manual; la app no detecta la marcha P.").setNegativeButton("Cancelar",null).setPositiveButton("Estoy estacionado",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"No hay una aplicación compatible para abrir el enlace",Toast.LENGTH_LONG).show();}}).show();}
 @Override protected void onPause(){stopGps();if(timer!=null)timer.reset();super.onPause();}
 @Override protected void onDestroy(){stopGps();super.onDestroy();}
}
